```go
// Go binding sketch (kv.go)
/*
#include "kv.h"
*/
import "C"

type KVStore struct{ ptr *C.kv_store }

func OpenStore() (*KVStore, error) { p := C.kv_open(); if p == nil { return nil, fmt.Errorf("open failed") }; return &KVStore{ptr: p}, nil }
func (s *KVStore) Close() error { C.kv_close(s.ptr); return nil }
func (s *KVStore) Set(key, value string) error { ck := C.CString(key); cv := C.CString(value); defer C.free(unsafe.Pointer(ck)); defer C.free(unsafe.Pointer(cv)); if C.kv_set(s.ptr, ck, cv) != 0 { return fmt.Errorf("set failed") }; return nil }
func (s *KVStore) Get(key string) (string, error) { ck := C.CString(key); defer C.free(unsafe.Pointer(ck)); var val *C.char; if C.kv_get(s.ptr, ck, &val) != 0 { return "", fmt.Errorf("get failed") }; goStr := C.GoString(val); C.kv_free_value(val); return goStr, nil }
```

