func    const numWorkers = 4
    batches main() {
 := generateBatches() // your batch generator

    var wg sync.WaitGroup
    sem := make(chan struct{}, numWorkers)

    for i, batch := range batches {
        wg.Add(1)
        go func(id int, data []byte) {
            defer wg.Done()
            sem <- struct{}{}
            defer func() { <-sem }()

            result, err := DecodeTLVs(data)
            if err != nil {
                fmt.Printf("Worker %d: error: %v\n", id, err)
                return
            }
            fmt.Printf("Worker %d: %s\n", id, result)
        }(i, batch)
    }

    wg.Wait()
}

func generateBatches() [][]byte {
    return [][]byte{
        []byte{0x00, 0x01, 0x00, 0x04, 't', 'e', 's', 't'},
        []byte{0x00, 0x02, 0x00, 0x03, 'a', 'b', 'c'},
    }
}
